public class Main {
  public static String dotStuff(String line) {
    return line.startsWith(".") ? "." + line : line;
  }

  public static String dotUnstuff(String line) {
    return line.startsWith(".") ? line.substring(1) : line;
  }

  public static void main(String[] args) {
    String[] samples = {".", "..", ".Hello", "Normal line."};
    for (String s : samples) {
      String wire = dotStuff(s);
      String decoded = dotUnstuff(wire);
      System.out.println(s + " -> " + wire + " -> " + decoded);
    }
  }
}

