  Recv["Incoming Email at Recipient MTA"] --> SPF["SPF Check:\nDoes Sender IP match TXT of MAIL FROM domain?"]
  Recv --> DKIM["DKIM Check:\nDoes Signature verify via DNS Public Key?"]
  SPF --> DMARC{"DMARC Alignment:\nDoes From: header domain match\npassing SPF or DKIM domain?"}
  DKIM --> DMARC
  DMARC -->|"Aligned Pass"| Deliver["Deliver to Inbox"]
  DMARC -->|"Fail: p=none"| Monitor["Deliver / Flag + Send rua= Report"]
  DMARC -->|"Fail: p=quarantine"| Spam["Move to Spam / Quarantine"]
  DMARC -->|"Fail: p=reject"| Reject["Reject Email (550)"]

