import java.io.BufferedReader;
import java.io.IOException;
import java.io.StringReader;

public class Main {
  public static String expect(BufferedReader in, int code) throws IOException {
    String line;
    do {
      line = in.readLine();
      if (line == null) {
        throw new IOException("The server closed the connection");
      }
    } while (line.length() > 3 && line.charAt(3) == '-');

    if (!line.startsWith(code + "")) {
      throw new IOException("Expected " + code + ", received: " + line);
    }
    return line;
  }

  public static void main(String[] args) throws IOException {
    String ehloReply = "250-mailpit greets client\r\n250-SIZE 52428800\r\n250 8BITMIME\r\n";
    BufferedReader okReader = new BufferedReader(new StringReader(ehloReply));
    System.out.println("Final: " + expect(okReader, 250));

    BufferedReader errReader = new BufferedReader(new StringReader("550 No such user\r\n"));
    try {
      expect(errReader, 250);
    } catch (IOException e) {
      System.out.println("Caught: " + e.getMessage());
    }
  }
}

